Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int n;
int totalStates;
int popcount[250], idx[250];
int f[10][250];
vector<int> groups[10];
map<pair<int, long long>, int> memoization;

int modInverse(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % MOD;
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int dfs(int layer, long long mask) {
    if (mask == 0) return 0;
    if (layer == n) return 1;
    auto key = make_pair(layer, mask);
    if (memoization.count(key)) return memoization[key];

    totalStates++;
    int total = 0;
    for (int subset_mask = 1; subset_mask <= (1 << n) - 1; ++subset_mask) {
        long long next_mask = 0;
        for (size_t k = 0; k < groups[layer].size(); ++k) {
            if (!(mask & (1LL << k))) continue;
            int prevVal = groups[layer][k];
            for (int l = 0; l < n; ++l) {
                if ((subset_mask & (1 << l)) && !(prevVal & (1 << l))) {
                    next_mask |= 1LL << idx[prevVal | (1 << l)];
                }
            }
        }
        total = (total + (long long)f[layer][subset_mask] * dfs(layer + 1, next_mask)) % MOD;
    }
    memoization[key] = total;
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    int inv100 = modInverse(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        f[i][0] = 1;
        for (int j = 0; j < n; ++j) {
            int P;
            cin >> P;
            int p1 = (long long)P * inv100 % MOD;
            int p0 = (MOD + 1 - p1) % MOD;
            for (int k = 0; k < (1 << j); ++k) {
                f[i][k | (1 << j)] = (long long)f[i][k] * p1 % MOD;
                f[i][k] = (long long)f[i][k] * p0 % MOD;
            }
        }
    }
    for (int i = 0; i < (1 << n); ++i) {
        popcount[i] = __builtin_popcount(i);
    }
    for (int i = 0; i < (1 << n); ++i) {
        groups[popcount[i]].push_back(i);
        idx[i] = (int)groups[popcount[i]].size() - 1;
    }
    cout << dfs(0, 1LL) << "\n";
    return 0;
}
